args.sparql:
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT DISTINCT ?film ?director ?directorLabel WHERE {
  ?film rdfs:label "Mary Jane's Pa"@en .
  OPTIONAL { ?film dbo:director ?director. }
  OPTIONAL { ?film dbp:director ?director. }
  OPTIONAL { ?director rdfs:label ?directorLabel FILTER(lang(?directorLabel) = "en") }
  FILTER ( !isBlank(?film) )
}

PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT DISTINCT ?director ?deathPlace ?deathPlaceLabel WHERE {
  BIND(dbr:William_Keighley AS ?director)
  OPTIONAL { ?director dbo:deathPlace ?deathPlace. }
  OPTIONAL { ?director dbp:death_place ?deathPlace. }
  OPTIONAL { ?deathPlace rdfs:label ?deathPlaceLabel FILTER(lang(?deathPlaceLabel) = "en") }
} LIMIT 50

